-- =========================================================
--  ITV Corporate — Terjemahan Konten (EN / JA)
--  ---------------------------------------------------------
--  Menambahkan kolom `translations` (JSON) ke tabel konten dan
--  mengisi terjemahan English + Japanese.
--
--  Jalankan SEKALI, idempotent (aman diulang):
--    mysql -u itv_user -p itv_corporate < server/schema-i18n.sql
--
--  PENTING: JANGAN jalankan server/init-db.js — skrip itu akan
--  menimpa logo/banner yang sudah diunggah lewat CMS.
-- =========================================================

SET NAMES utf8mb4;
-- ---------- 1. Tambah kolom translations ----------
ALTER TABLE `services` ADD COLUMN IF NOT EXISTS `translations` JSON NULL COMMENT 'Terjemahan EN/JA per field';
ALTER TABLE `products` ADD COLUMN IF NOT EXISTS `translations` JSON NULL COMMENT 'Terjemahan EN/JA per field';
ALTER TABLE `sectors` ADD COLUMN IF NOT EXISTS `translations` JSON NULL COMMENT 'Terjemahan EN/JA per field';
ALTER TABLE `banners` ADD COLUMN IF NOT EXISTS `translations` JSON NULL COMMENT 'Terjemahan EN/JA per field';
ALTER TABLE `articles` ADD COLUMN IF NOT EXISTS `translations` JSON NULL COMMENT 'Terjemahan EN/JA per field';

-- ---------- 2. Seed terjemahan EN + JA ----------

-- services (4 baris)
UPDATE `services` SET `translations` = '{"en":{"title":"Smart Display & Digital Signage","description":"A centralized display network for internal communication, promotion, and real-time operational information.","features":["Digital Signage Standing & Wall-Mount","Interactive Kiosk","Interactive Whiteboard","Indoor / Outdoor Videotron","Video Wall & Centralized CMS"]},"ja":{"title":"スマートディスプレイ＆デジタルサイネージ","description":"社内コミュニケーション、プロモーション、リアルタイムの運用情報を伝える集中型ディスプレイネットワーク。","features":["デジタルサイネージ スタンド型・壁掛け型","インタラクティブキオスク","インタラクティブホワイトボード","屋内・屋外ビデオトロン","ビデオウォール＆統合CMS"]}}'
  WHERE `slug` = 'smart-display' AND (`translations` IS NULL OR JSON_LENGTH(`translations`) = 0);
