-- ---------- 3. Verifikasi ----------
SELECT 'services' AS tabel, COUNT(*) AS total,
       SUM(translations IS NOT NULL) AS diterjemahkan FROM services
UNION ALL SELECT 'products', COUNT(*), SUM(translations IS NOT NULL) FROM products
UNION ALL SELECT 'sectors', COUNT(*), SUM(translations IS NOT NULL) FROM sectors
UNION ALL SELECT 'banners', COUNT(*), SUM(translations IS NOT NULL) FROM banners
UNION ALL SELECT 'articles', COUNT(*), SUM(translations IS NOT NULL) FROM articles;
